-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elemental"
L["rm.era.shaman.elemental.Description"] = "Elemental from level 10 (most points in Elemental); built from Icy Veins and Wowhead. Earth Shock interrupts and finishes a target about to die. While moving: Flame Shock, else Frost Shock. Solo with the target in melee: Earth Shock above 30% health, then melee. On three or more enemies: Fire Nova and Magma totems when you are in melee, and Chain Lightning. Chain Lightning under Elemental Mastery or Clearcasting, otherwise Lightning Bolt. Reminders: Lightning Shield, Rockbiter outside raids, Searing or Magma, Mana Spring or Healing Stream, Elemental Mastery with Chain Lightning ready, Nature's Swiftness and Healing Wave below 30%, healing after a pull. Dispels, purges and downranking stay with you."
L["rm.era.shaman.elemental.simulator.Name"] = "Elemental, Chain Lightning on cooldown (simulator)"
L["rm.era.shaman.elemental.simulator.Description"] = "The simulator Elemental list, an alternative to the recommended Elemental premade, off by default: enable it and disable that one, or raise its priority. Chain Lightning on cooldown even on one target, Earth Shock while Elemental Mastery is up, otherwise Lightning Bolt. Faster but much hungrier for mana than the recommended premade; same interrupt, totems and reminders."
L["rm.era.shaman.enhancement.Name"] = "Enhancement"
L["rm.era.shaman.enhancement.Description"] = "Levels 1–60, also on Hardcore and Self-Found realms, and every Shaman without a talent majority; built from Icy Veins, Wowhead and simulator. Lightning Bolt pulls from range; Earth Shock interrupts. In raids only Stormstrike and Frost Shock (debuff slots). On three or more enemies fighting you, Fire Nova and Magma totems. Then Stormstrike, Earth Shock into the Stormstrike debuff or to finish, Flame Shock when it will run its course, Earth Shock while you have half your mana, and Lightning Bolt while out of reach. Reminders: Rockbiter solo and Windfury Weapon in dungeons, Lightning Shield, Strength of Earth, Searing, Windfury or Grace of Air, Mana Spring or Healing Stream, healing after a pull and in emergencies. Stoneclaw, Earthbind, totem twisting and racials are listed off; dispels, purges and cleansing totems stay with you."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Enhancement, Flame Shock first (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Warcraft Tavern's Enhancement, an alternative to the recommended Enhancement premade, off by default: enable it and disable that one, or raise its priority. Windfury Weapon as soon as you learn it, Stormstrike, Flame Shock before any direct shock, then Earth Shock while your threat is low, or Frost Shock in a group once it is high; Magma and Chain Lightning on packs. Same totems and reminders as the recommended premade."
L["rm.era.shaman.restoration.Name"] = "Restoration"
L["rm.era.shaman.restoration.Description"] = "Restoration from level 10 (most points in Restoration); built from Icy Veins and Wowhead. On your friendly target: Healing Wave under Nature's Swiftness, Nature's Swiftness below 30%, Lesser Healing Wave below 40%, Cure Poison or Cure Disease, Chain Heal when three group members near you are below 85%, otherwise Healing Wave below 90%. On an enemy it fights: Earth Shock interrupt, Chain Lightning on packs, Flame Shock, Lightning Bolt from range, melee. Reminders: Lightning Shield and Rockbiter solo, Mana Tide in a group, Mana Spring, Strength of Earth, Searing. Choosing whom to heal, downranking and Tremor or cleansing totems stay with you; keeping Healing Way on the tank is listed off."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Restoration, Chain Heal first (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Warcraft Tavern's Restoration, an alternative to the recommended Restoration premade, off by default: enable it and disable that one, or raise its priority. Chain Heal is the heal for anyone below 90%, with Lesser Healing Wave for someone about to die; Healing Wave is only for an assigned tank healer with Healing Way (listed off). Same cures, damage on enemies and totem reminders as the recommended premade."
L["rm.forever.shaman.elemental.Name"] = "Elemental"
L["rm.forever.shaman.elemental.Description"] = "Ranged Elemental once Elemental is your main talent tree with 21 points (Lava Burst's tier), after Icy Veins (before that the Enhancement premade plays the melee hybrid every guide recommends). Pulls with Lightning Bolt (Chain Lightning on a pack), casts only instants while moving, uses Fire Nova and Chain Lightning on three or more enemies, keeps Flame Shock up, Lava Burst on cooldown, Stormstrike and Earth Shock if you know Stormstrike, Fire Nova on Clearcasting in groups, then Lightning Bolt. Reminders: shield, weapon imbue, Searing or Magma Totem, group totems, Elemental Mastery, interrupt. Health and mana are hidden from addons on Forever, so healing yourself and pausing to refill mana are your call. Left to you: Earthbind kiting, Frost Shock, Purge and other totems."
L["rm.forever.shaman.enhancement.Name"] = "Enhancement (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Melee Enhancement from level 1 to 60, and the default for any Shaman before Lava Burst or Mana Tide Totem. Pulls with Lightning Bolt from range, then Stormstrike on cooldown, an instant Lightning Bolt at five Maelstrom Weapon stacks, Fire Nova (with a Fire totem down) and Flame Shock on three or more enemies, Earth Shock into the Stormstrike debuff, Flame Shock in groups, and Earth Shock on cooldown; Lightning Bolt fills the gap while the target is out of reach. Health and mana are hidden from addons on Forever, so healing yourself and pausing to refill mana are your call (the Wowhead premade saves mana instead). Reminders: weapon imbue (Windfury, else Flametongue, else Rockbiter), Water or Lightning Shield, the Earth Shock interrupt, Searing or Magma Totem, group totems, Rage of the Farseer, Stoneclaw Totem. Left to you: totem presets, Frost Shock, Purge and other totems."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Enhancement, mana-efficient (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Wowhead's and Mobalytics' mana-saving Enhancement: auto-attack does the work, Stormstrike only while Improved Stormstrike's mana regeneration is down, no Earth Shock in the rotation (shocks pull and interrupt), and in groups or on packs Searing Totem with Fire Nova on cooldown. Same imbue, shield and interrupt reminders as the Icy Veins premade. Choose it instead of that premade if mana runs out. An alternative to the recommended Enhancement premade, off by default: enable it and disable that one, or raise its priority."
L["rm.forever.shaman.restoration.Name"] = "Restoration"
L["rm.forever.shaman.restoration.Description"] = "Healing once Restoration is your main talent tree with 16 points (Mana Tide Totem's tier), after Icy Veins. With a friendly target: an instant Healing Wave once you use Nature's Swiftness, Cure Poison and Cure Disease, Riptide on a target without it, Chain Heal in a group, Healing Wave. You pick who to heal by targeting them; health and mana are hidden from addons on Forever, so when to use Nature's Swiftness and Lesser Healing Wave is your call. With a hostile target and nothing to heal: Fire Nova and Chain Lightning on packs, Stormstrike and Earth Shock if you know Stormstrike, Flame Shock on elites and bosses, Lightning Bolt, then melee. Reminders: Water Shield, the Earth Shock interrupt, Mana Tide and group buff totems. Left to you: downranking, other totems, Purge and Ghost Wolf."
L["rm.mop.shaman.elemental.Name"] = "Recommended"
L["rm.mop.shaman.elemental.Description"] = "Recommended for Elemental from level 10, chosen in the Elemental specialization. Wowhead's order: a Lightning Bolt to open (Lava Burst with Unleashed Fury), Unleash Elements with Unleashed Fury, Flame Shock when it is missing or about to run out on a target that will live, Lava Burst into Flame Shock (and on every Lava Surge), Elemental Blast, Earth Shock at six Lightning Shield charges while Flame Shock has 6 seconds left, Chain Lightning on two enemies, Lightning Bolt. Four or more enemies on you: Magma in melee, free Lava Bursts, Lava Beam in Ascendance, Chain Lightning. While moving it shows only instants. Reminders: Lightning Shield, Flametongue, Searing Totem, Fire Elemental on elites and bosses, Elemental Mastery, Ascendance after a Lava Burst, Ancestral Swiftness, Stormlash and Bloodlust in a group, Wind Shear, Thunderstorm for mana, Shamanistic Rage and Astral Shift when low. Earthquake and Earth Elemental are listed but off. Left to you: Spiritwalker's Grace, Flame Shock on extra targets and where to stand."
L["rm.mop.shaman.enhancement.Name"] = "Recommended"
L["rm.mop.shaman.enhancement.Description"] = "Recommended for Enhancement from level 10, chosen in the Enhancement specialization. Wowhead's order: Unleash Elements while running in, then Unleash Elements with Unleashed Fury, Elemental Blast and Lightning Bolt at five Maelstrom Weapon (or woven at three when your next swing is over a second away), Stormblast in Ascendance, Stormstrike (Primal Strike before 26), Lava Lash, Flame Shock under Unleash Flame, Unleash Elements, Earth Shock. Two or more enemies on you: Chain Lightning instead of Lightning Bolt, Lava Lash to spread Flame Shock, Fire Nova from four, Magma from six. Reminders: Lightning Shield, Windfury on the main hand and Flametongue on the off hand, Searing Totem, Fire Elemental, Feral Spirit, Ascendance after Stormstrike, Elemental Mastery, Ancestral Swiftness, Stormlash and Bloodlust in a group, Wind Shear, Shamanistic Rage and Astral Shift when low. Earth Elemental is listed but off."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Lava Lash first (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Off by default; same switch as the recommended Enhancement premade, so enable it and disable that one to use it. Icy Veins' order: Stormstrike, then Lava Lash before spending Maelstrom Weapon, Lightning Bolt at five stacks or from three when it lands before your next swing, Unleash Elements then Flame Shock, Earth Shock. On four or more enemies it spreads Flame Shock with Lava Lash and uses Fire Nova; Chain Lightning replaces Lightning Bolt on packs. Shamanistic Rage is suggested on cooldown in combat; other reminders as the recommended premade."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Weave every stack (simulator)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Off by default; same switch as the recommended Enhancement premade, so enable it and disable that one to use it. The simulator's list for players who time casts between swings: Lightning Bolt, Elemental Blast or Chain Lightning on any number of Maelstrom Weapon stacks whenever the cast finishes before your next main-hand swing, Unleash Elements also whenever Flame Shock is missing, and Earth Shock only below two stacks. Reminders as the recommended premade."
L["rm.mop.shaman.restoration.Name"] = "Recommended"
L["rm.mop.shaman.restoration.Description"] = "Recommended for Restoration from level 10, chosen in the Restoration specialization. Heals your friendly target (Rotation Master cannot pick who to heal): Greater Healing Wave under Ancestral Swiftness, Healing Surge below 35%, Purify Spirit on Magic or Curses, Unleash Elements then Healing Rain when three allies nearby are hurt, Riptide, Chain Heal for group damage, Greater Healing Wave below 60%, Healing Wave below 90%. With an attackable target it deals damage instead (Flame Shock, Lava Burst, Elemental Blast, Lightning Bolt). Reminders: Water Shield, Earthliving, Earth Shield on your focus, Healing Stream when someone is hurt, Mana Tide, Healing Tide for heavy group damage, Elemental Mastery or Ancestral Guidance, Ancestral Swiftness on a low target, Spiritwalker's Grace while moving, Bloodlust, Wind Shear. Ascendance and Spirit Link Totem are listed but off: use them when your raid assigns them."
L["rm.mop.shaman.restoration.hekili.Name"] = "Health ladder (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Off by default; same switch as the recommended Restoration premade, so enable it and disable that one to use it. Hekili's list keeps Earth Shield and Riptide on your target and Healing Stream and Healing Rain going whenever they are down, then heals by the average health of your group within 40 yards: Chain Heal below 80%, Healing Wave on a target below 70%, Greater Healing Wave below 60%, Healing Surge below 40%, with Healing Tide, Ancestral Guidance and Mana Tide on the same ladder. An attackable target gets damage plus Earth Shock."
L["rm.mop.shaman.unspecialized.Name"] = "Unspecialized"
L["rm.mop.shaman.unspecialized.Description"] = "For levels 1 to 9, and any Shaman who has not chosen a specialization yet; every specialization premade takes over once you pick one. Lightning Bolt to pull from range, Healing Surge when you are low and alone, Primal Strike, Earth Shock, and Lightning Bolt while out of melee range. Keeps Lightning Shield up."
L["rm.retail.shaman.elemental.Name"] = "Blizzard Assisted"
L["rm.retail.shaman.elemental.Description"] = "Recommended for Elemental in Midnight. In combat the game now hides Flame Shock, your buffs, Maelstrom, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat suggestion (the one-button rotation), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: Ascendance, Fire or Storm Elemental and Nature's Swiftness in combat, Spiritwalker's Grace while moving, Lightning Shield and Skyfury between pulls (Blizzard's suggestion keeps your weapon and shield imbues), Wind Shear on an interruptible cast (it lights only where the game lets the cast be read), Astral Shift whenever it is ready in combat (health is hidden on Retail, so when to use it is your call)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order reads Flame Shock, Master of the Elements and Stormkeeper, which Midnight hides in combat; Maelstrom is hidden on Retail, so the spenders go at their cost instead of near full Maelstrom. Stormkeeper and Lava Burst before the pull. On three or more engaged enemies: Stormkeeper, Ancestral Swiftness, Flame Shock, Chain Lightning with Stormkeeper, Elemental Blast, Earthquake, Lava Burst on Lava Surge, Tempest, Chain Lightning. Otherwise Stormkeeper, Ancestral Swiftness, Flame Shock and Voltaic Blaze in their last 30% outside Master of the Elements, Lava Burst to start it, Tempest and Stormkeeper's Lightning Bolt inside it, Elemental Blast or Earth Shock inside it, Voltaic Blaze, Tempest, Flame Shock or Frost Shock while moving, Elemental Blast or Earth Shock whenever you can afford it, Lightning Bolt. Reminders: Ascendance once Stormkeeper is used, elementals, Spiritwalker's Grace, and the shared ones."
L["rm.retail.shaman.enhancement.Name"] = "Blizzard Assisted"
L["rm.retail.shaman.enhancement.Description"] = "Recommended for Enhancement in Midnight. Shows Blizzard's Assisted Combat suggestion (it spends Maelstrom Weapon, keeps Flame Shock and handles Surging Totem and Sundering), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: Ascendance, Doom Winds and Feral Spirit in combat, Lightning Shield and Skyfury between pulls (Blizzard's suggestion keeps Windfury Weapon), Wind Shear, Astral Shift."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Stormbringer reference (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Reference only, off by default: SimulationCraft's Stormbringer list (Icy Veins and Wowhead agree) reads Flame Shock, Crash Lightning, Lashing Flames and cooldown timers, which Midnight hides in combat. On three or more engaged enemies: Crash Lightning for its buff, Tempest at 10 Maelstrom Weapon, Chain Lightning at 9, Crash Lightning, Lava Lash, Sundering. Then Primordial Storm at 9, Voltaic Blaze or Flame Shock when Flame Shock is missing, Sundering, Crash Lightning for its buff, Lava Lash for Lashing Flames, Windstrike, Tempest or Lightning Bolt at 10 (8 with Voltaic Blaze or Crash Lightning about ready), Stormstrike at two charges, Lava Lash, Stormstrike, Voltaic Blaze, Crash Lightning, Lightning Bolt at 5, Flame Shock. Reminders: Doom Winds, Ascendance outside Doom Winds, Feral Spirit, and the shared ones."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totemic reference (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Reference only, off by default: SimulationCraft's Totemic list reads Flame Shock, Hot Hand, Whirling Fire, Crash Lightning and Doom Winds, which Midnight hides in combat. On three or more engaged enemies: Crash Lightning, Chain Lightning at 5 Maelstrom Weapon. Then Voltaic Blaze or Flame Shock when Flame Shock is missing, Surging Totem, Sundering, Lava Lash with Hot Hand or Whirling Fire, Crash Lightning for its buff, Primordial Storm at 10, Windstrike, Crash Lightning and Stormstrike in Doom Winds, Lightning Bolt at 5, Crash Lightning, Lava Lash, Stormstrike, Voltaic Blaze, Flame Shock. Same reminders as the Stormbringer reference."
L["rm.retail.shaman.initial.Name"] = "Blizzard Assisted"
L["rm.retail.shaman.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Shaman's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Shaman premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Restoration in Midnight, for reference: Blizzard's Assisted Combat does not cover healers, the game hides everyone's health in combat and Rotation Master picks a spell, not a target, so this orders your healing tools by readiness on whatever you target and leaves deciding who to heal to you. On a friendly target: Healing Stream Totem, Unleash Life, Healing Rain in a group, Surging Totem, Riptide, Chain Heal in a group, Healing Wave. On an enemy: Flame Shock when missing, Lava Burst, Lightning Bolt. Reminders: Water Shield, Earth Shield on a friendly target and Skyfury between pulls; Nature's Swiftness in combat; Healing Tide Totem and Spirit Link Totem in grouped combat; Wind Shear; Astral Shift."
L["rm.sod.shaman.elemental.Name"] = "Elemental (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Season of Discovery Elemental from level 10 (most points in Elemental); built from simulator Phase 6, Wowhead and Icy Veins. Earth Shock interrupts. While moving: Flame Shock, Earth Shock at eight Lightning Shield charges, Lava Burst or Chain Lightning on a Power Surge proc. On three or more enemies: Flame Shock, Chain Lightning, Fire Nova, Lava Burst, Earth Shock at eight charges, Magma. Then Lava Burst on Power Surge, Flame Shock kept up, Lava Burst while your Flame Shock lasts, Earth Shock at eight charges, Chain Lightning on two enemies, Lightning Bolt. Reminders: Flametongue for Burn, Lightning Shield, Earth Shield on yourself, Spirit of the Alpha, Feral Spirit, Shamanistic Rage, Elemental Mastery, totems. Trinkets, Totemic Projection, dispels and purges stay with you."
L["rm.sod.shaman.enhancement.Name"] = "Enhancement (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Season of Discovery, levels 1–60 with runes as you engrave them, dual wield or two-hander, and every SoD Shaman no other premade fits; built from simulator Phase 6, Icy Veins and Wowhead. Flame Shock pulls; Earth Shock interrupts. On three or more enemies: Magma, Fire Nova from a fire totem, Chain Lightning at four Maelstrom stacks, Flame Shock. Then Lava Burst at five Maelstrom stacks, Stormstrike, Lava Lash, Lightning Bolt at five stacks, Flame Shock when it will run, Earth Shock, Molten Blast, Lightning Bolt from range. Reminders: Windfury Weapon (Rockbiter before), Flametongue on an off-hand weapon with Lava Lash (else Windfury; never on a shield; an Icy Veins Windfury-both line is listed off), Water or Lightning Shield, Spirit of the Alpha, Feral Spirit, Shamanistic Rage below 65% mana, totems, Ancestral Guidance. Totemic Projection, dispels and purges stay with you."
L["rm.sod.shaman.restoration.Name"] = "Restoration (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Season of Discovery Restoration from level 10 (most points in Restoration); built from Icy Veins and Wowhead. On your friendly target: Riptide then Lesser Healing Wave below 40%, Cure Poison or Cure Disease, Healing Rain when three group members near you are below 85%, Chain Heal when two are (at once on a Power Surge proc), Riptide below 95% for Tidal Waves, Healing Wave below 90%. On an enemy it fights. Reminders: Water Shield (Lightning Shield before), Earth Shield on your friendly target or yourself, Shamanistic Rage, Mana Tide, Mana Spring and Strength of Earth. Choosing whom to heal and Tremor or cleansing totems stay with you."
L["rm.sod.shaman.tank.Name"] = "Tank (SoD, Way of Earth)"
L["rm.sod.shaman.tank.Description"] = "Season of Discovery tank, chosen once Way of Earth is engraved; built from Icy Veins, Wowhead, simulator and Warcraft Tavern. Flame Shock pulls. Earth Shock taunts a target in melee that is not attacking you, and interrupts. On two or more enemies: Molten Blast, Flame Shock, Chain Lightning at five Maelstrom stacks or on Power Surge, Fire Nova at five stacks. Then Flame Shock kept up, Lava Burst on Power Surge or while Flame Shock lasts, Stormstrike, Earth Shock, Lightning Bolt at five stacks, Molten Blast, Frost Shock. Reminders: Rockbiter, Lightning Shield, Spirit of the Alpha on yourself, Feral Spirit, Shamanistic Rage, Searing or Magma, and group totems."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elemental (Icy Veins & simulator)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Caster Elemental for the Elemental talent tree. Lightning Bolt is the filler; Chain Lightning goes out with Elemental Mastery, on Clearcasting while you have 40% mana, or freely above 80%; Flame Shock only while moving; Earth Shock interrupts; Fire Nova, Chain Lightning and Magma for packs. Before Chain Lightning a target in melee is left to auto-attack to save mana. Reminders: Water or Lightning Shield, a weapon imbue, Totem of Wrath (or Searing on long fights), Wrath of Air, Mana Spring, Totemic Call after the fight, Elemental Mastery and Bloodlust/Heroism."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elemental (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "NextActionTBC's Elemental, an alternative to the recommended Icy Veins Elemental premade, off by default: enable it and disable that one, or raise its priority. Keeps Flame Shock on the target, Chain Lightning only against two or more enemies while above 30% mana, Lightning Bolt otherwise. Reminds you of Lightning Shield, a weapon imbue, Elemental Mastery and Bloodlust/Heroism; totems stay manual."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elemental (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "Wowhead's Elemental, an alternative to the recommended Icy Veins Elemental premade, off by default: enable it and disable that one, or raise its priority. At 70 Chain Lightning on cooldown with Lightning Bolts in between (while leveling only with Elemental Mastery or Clearcasting), Flame Shock only while moving, Earth Shock to finish a target that would die before a cast lands. Same totem, shield and cooldown reminders as the Icy Veins variant."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Enhancement (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Melee Enhancement from level 1 to 70, and the default for any Shaman no other premade fits. Pulls with Lightning Bolt from range, interrupts with Earth Shock, drops Fire Nova and Magma Totems on three or more nearby enemies, then Stormstrike, Earth Shock while Stormstrike's debuff is up, Flame Shock on a target that will live, Earth Shock on cooldown, and Lightning Bolt while the target is out of reach. Separate reminders: weapon imbues, Water or Lightning Shield, Strength of Earth, Windfury (group) or Grace of Air (solo), Searing on long fights, water totems, Shamanistic Rage, Bloodlust/Heroism on bosses, Stoneclaw and Earth Elemental when solo. Fire Elemental is an optional step that starts off. Totem placement, Ghost Wolf and healing stay with you."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Enhancement (Wowhead & simulator)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "The level-70 raid model for totem twisting, an alternative to the recommended Icy Veins Enhancement premade, off by default: enable it and disable that one, or raise its priority. Stormstrike, a Fire Nova Totem weave, Flame Shock whenever it has fallen off, and Earth Shock as the main shock, with Lightning Bolt only out of reach. Reminders twist Windfury and Grace of Air Totems, keep Searing down, use Shamanistic Rage when mana runs low, and share the Icy Veins variant's imbue, shield and totem upkeep."
L["rm.tbc.shaman.restoration.Name"] = "Restoration"
L["rm.tbc.shaman.restoration.Description"] = "Healing for the Restoration talent tree, on your friendly target (or yourself with no target): Nature's Swiftness and Healing Wave or Lesser Healing Wave in emergencies, Cure Poison and Cure Disease, Earth Shield on your focus, Chain Heal when three nearby allies are hurt, Healing Wave otherwise. With a hostile target it switches to Flame Shock and Lightning Bolt for soloing. Reminders: Water Shield, Earth Shield on your focus (set the tank as focus), Mana Tide, Mana Spring and Strength of Earth in a group, Bloodlust/Heroism. Choosing whom to heal and which rank stays with you."
